insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g5_ela_v1'
from (values
('110.7.b.3.A',3,'Which part of a dictionary entry shows where a word came from?','["the etymology", "the guide words", "the cover", "the page number"]'::jsonb,0,'Word origin is the etymology.','original'),
('110.7.b.3.A',3,'A dictionary shows "re-cy-cle." What does this tell the reader?','["who wrote the word", "how the word is divided into syllables", "when the word was invented", "what the word rhymes with"]'::jsonb,1,'The hyphens show syllables.','original'),
('110.7.b.3.B',3,'"The comedian''s jokes were so hilarious that the audience roared with laughter." What does hilarious mean?','["quite boring", "a little scary", "extremely funny", "very sad"]'::jsonb,2,'The audience roared with laughter.','original'),
('110.7.b.3.B',4,'"Sam''s reluctant smile showed he did not really want to go to the dentist." What does reluctant mean?','["proud", "careless", "excited", "unwilling"]'::jsonb,3,'He did not want to go.','original'),
('110.7.b.3.B',3,'In "The river bank was muddy" and "She went to the bank to deposit money," how can a reader tell the meaning of bank?','["by the words around it", "by its first letter", "by its length", "by the page number"]'::jsonb,0,'Context clues show the meaning.','original'),
('110.7.b.3.C',3,'The prefix trans- means across. What does "transatlantic" most likely mean?','["under the sea", "across the Atlantic Ocean", "near the beach", "before the ocean"]'::jsonb,1,'Trans means across.','original'),
('110.7.b.3.C',3,'The prefix super- means above or beyond. What does "superhuman" mean?','["a pet", "like a small human", "beyond what humans normally can do", "less than human"]'::jsonb,2,'Super means beyond.','original'),
('110.7.b.3.C',3,'The suffix -logy means "the study of." What does "geology" mean?','["the study of words", "the study of stars", "the study of animals", "the study of the Earth"]'::jsonb,3,'Geo means Earth.','original'),
('110.7.b.3.C',4,'The root "photo" means light. What does "photosynthesis" involve?','["using light to make food", "building a house", "making noise", "breaking rocks"]'::jsonb,0,'Photo means light.','original'),
('110.7.b.3.D',3,'"A stitch in time saves nine" is an example of...','["a metaphor", "an adage", "a pun", "a rhyme scheme"]'::jsonb,1,'An adage is a short wise saying.','original'),
('110.7.b.3.D',4,'"I used to be a baker, but I couldn''t make enough dough." This joke plays on a word with two meanings. It is a...','["a fact", "a simile", "pun", "an adage"]'::jsonb,2,'A pun uses a word with two meanings.','original'),
('110.7.b.3.D',3,'What does the adage "Look before you leap" advise?','["look at the sky", "run fast", "jump high", "think before acting"]'::jsonb,3,'Be careful before you act.','original'),
('110.7.b.6.A',3,'A student sets a purpose before reading a science article on volcanoes. Which is the best purpose?','["to learn how volcanoes form", "to guess the author''s age", "to count the commas", "to copy the font"]'::jsonb,0,'A purpose guides reading.','original'),
('110.7.b.6.B',3,'Which question could a reader ask during reading to better understand a biography of an inventor?','["How many pages are left?", "What problem was the inventor trying to solve?", "What color is the book cover?", "Where is the library?"]'::jsonb,1,'It deepens understanding.','original'),
('110.7.b.6.C',3,'A nonfiction article has a section called "How Hurricanes Form." What might the reader predict about it?','["it will show a map of a mall", "it will list recipes", "it will explain the steps of how hurricanes develop", "it will tell a funny story"]'::jsonb,2,'Headings suggest content.','original'),
('110.7.b.6.D',3,'Which sentence is best for creating a mental image of a thunderstorm?','["It was a day.", "There was weather.", "Storms happen.", "Lightning split the dark sky as thunder rattled the windows."]'::jsonb,3,'Sensory details build images.','original'),
('110.7.b.6.E',3,'A student reads about a flood and thinks of a news story about a rescue. This is a connection to...','["society", "punctuation", "spelling", "handwriting"]'::jsonb,0,'It links to events in the world.','original'),
('110.7.b.6.F',4,'Read: "Dani kept glancing at the clock and tapping her pencil as the teacher passed out the tests." What can you infer?','["Dani lost her pencil.", "Dani feels anxious about the test.", "Dani loves clocks.", "Dani is the teacher."]'::jsonb,1,'Her actions show nervousness.','original'),
('110.7.b.6.G',3,'Which detail best shows the key idea that bees are important to farming?','["Bees are small.", "Bees live in hives.", "They pollinate many crops.", "Bees can sting."]'::jsonb,2,'Pollination helps crops grow.','original'),
('110.7.b.6.H',4,'One article explains how plants make food. Another explains how animals eat plants. What new idea can a reader build by combining them?','["plants eat animals", "food grows on rocks", "animals make sunlight", "energy moves from plants to animals"]'::jsonb,3,'Combining sources shows energy flow.','original'),
('110.7.b.6.I',3,'A reader notices their mind wandering while reading a long paragraph. What is a good adjustment?','["reread and ask questions about the paragraph", "skip the paragraph", "read faster", "close the book"]'::jsonb,0,'Rereading and asking questions help.','original'),
('110.7.b.7.A',3,'Which sentence shows a personal connection to a book about moving to a new school?','["Schools have doors.", "I felt nervous like that on my first day at my school.", "The book has a blue cover.", "Moving trucks are big."]'::jsonb,1,'It links the reader''s experience.','original'),
('110.7.b.7.B',4,'Which written response compares two articles about volcanoes?','["Articles have titles.", "Volcanoes are hot.", "Both articles describe eruptions, but only one explains how scientists predict them.", "I read two things."]'::jsonb,2,'It shows a comparison.','original'),
('110.7.b.7.C',3,'Which sentence uses text evidence to support the idea that Marcus is generous?','["Marcus is in fifth grade.", "Marcus likes lunch.", "Marcus has a backpack.", "Marcus gave half of his lunch to a classmate who had forgotten his."]'::jsonb,3,'Sharing his lunch shows generosity.','original'),
('110.7.b.7.D',3,'Which is the best summary of a paragraph that explains how rain forms from water vapor rising, cooling, and falling?','["Water vapor rises, cools into clouds, and falls as rain.", "Clouds are white.", "Water is wet.", "Rain makes puddles."]'::jsonb,0,'It keeps the main events in order.','original'),
('110.7.b.7.E',3,'A student draws a diagram while reading a science chapter to remember the steps. This is an example of...','["changing the author", "interacting with the text by illustrating", "skipping details", "copying a title"]'::jsonb,1,'Illustrating is a way to interact with text.','original'),
('110.7.b.7.F',3,'After learning the word "ecosystem," which sentence uses it correctly?','["I wore an ecosystem on my head.", "The ecosystem ate lunch.", "A pond is an ecosystem with plants, animals, and water.", "Ecosystem is a type of sandwich."]'::jsonb,2,'It uses the word correctly.','original'),
('110.7.b.7.G',3,'During a class discussion about a story, which comment helps explain an important idea?','["My dog barks.", "The book is long.", "I like the pictures.", "The storm shows how nervous the characters feel."]'::jsonb,3,'It explains meaning.','original'),
('110.7.b.8.A',4,'A story shows a girl who is honest even when it is hard, and she also learns to forgive her friend. Which pair of themes fits?','["honesty and forgiveness", "money and fame", "winter and summer", "speed and strength"]'::jsonb,0,'Both ideas are shown.','original'),
('110.7.b.8.B',4,'Two brothers argue about who should lead their team. This is a conflict between...','["title and author", "characters", "stanzas", "setting and plot"]'::jsonb,1,'Characters disagree.','original'),
('110.7.b.8.B',3,'A character wants to reach the mountain top, but a storm blocks the trail. This conflict is between the character and...','["a teacher", "a family member", "nature", "a friend"]'::jsonb,2,'The storm is part of nature.','original'),
('110.7.b.8.C',3,'In a story, the most intense moment, when the main problem is faced, is the...','["title", "resolution", "exposition", "climax"]'::jsonb,3,'The climax is the turning point.','original'),
('110.7.b.8.C',3,'The part of a plot where the problem is finally solved is the...','["resolution", "introduction", "climax", "rising action"]'::jsonb,0,'The resolution ends the conflict.','original'),
('110.7.b.8.D',4,'A story is set in the Wild West in the 1800s. How does this historical setting influence the plot?','["it changes the author", "events like cattle drives and travel by horse shape what happens", "it removes characters", "it makes the story a poem"]'::jsonb,1,'The time period affects events.','original'),
('110.7.b.9.A',3,'Which genre often explains why something in nature exists, such as why the sun rises?','["map", "biography", "myth", "science report"]'::jsonb,2,'Myths explain natural events.','original'),
('110.7.b.9.A',3,'A folktale is a story that...','["is a math problem", "is a modern news article", "is a dictionary entry", "has been passed down by word of mouth"]'::jsonb,3,'Folktales are traditional.','original'),
('110.7.b.9.B',4,'In a poem, the speaker is...','["the voice that tells the poem", "the title", "the rhyme", "the author''s name"]'::jsonb,0,'The speaker is not always the poet.','original'),
('110.7.b.9.B',3,'"The stars winked at me" is an example of...','["a date", "personification", "a prefix", "a fact"]'::jsonb,1,'Stars are given a human action.','original'),
('110.7.b.9.B',3,'The line "Whispering winds were wailing" uses...','["rhyme", "dialogue", "alliteration", "onomatopoeia"]'::jsonb,2,'Repeated w sounds.','original'),
('110.7.b.9.C',3,'In a play script, the words in parentheses that describe how a character moves or speaks are...','["rhymes", "dialogue", "a theme", "stage directions"]'::jsonb,3,'Stage directions guide actors.','original'),
('110.7.b.9.C',3,'A play is organized into acts and...','["scenes", "chapters", "glossaries", "stanzas"]'::jsonb,0,'Acts are divided into scenes.','original'),
('110.7.b.9.D.i',3,'An article describes how the Amazon rain forest provides oxygen, shelter for animals, and medicines. What is the central idea?','["Rain is wet.", "The Amazon rain forest is valuable to many living things.", "Forests are green.", "Animals sleep."]'::jsonb,1,'The details support the central idea.','original'),
('110.7.b.9.D.ii',3,'A sidebar in a textbook is used to...','["list page numbers", "show the table of contents", "give extra information about the topic", "replace the main text"]'::jsonb,2,'Sidebars add details.','original'),
('110.7.b.9.D.ii',3,'A timeline in a history article helps the reader...','["learn spelling", "count pages", "find rhymes", "see events in order"]'::jsonb,3,'Timelines show sequence.','original'),
('110.7.b.9.D.iii',3,'An article lists reasons from least important to most important. The pattern is...','["order of importance", "chronological order", "description of a place", "compare and contrast"]'::jsonb,0,'The reasons build up.','original'),
('110.7.b.9.E.i',3,'Read: "Art builds creativity, so our schools should add art classes." What is the claim?','["Schools are big.", "Schools should offer more art classes.", "Art is colorful.", "Paint is wet."]'::jsonb,1,'The claim is the main argument.','original'),
('110.7.b.9.E.ii',4,'An author argues against littering and cites a study showing that litter harms wildlife. How does the study help the argument?','["It changes the topic.", "It adds a rhyme.", "It gives a fact that supports the claim.", "It makes the claim weaker."]'::jsonb,2,'Facts strengthen an argument.','original'),
('110.7.b.9.E.iii',3,'An ad says, "Kids, save your allowance for this great new game!" Who is the intended audience?','["pilots", "grandparents", "teachers", "children"]'::jsonb,3,'The ad addresses kids.','original'),
('110.7.b.9.F',3,'A website with a video, a map, and a clickable menu is an example of...','["a multimodal text", "a dictionary", "a poem", "a diary"]'::jsonb,0,'It uses several modes.','original'),
('110.7.b.10.A',3,'A story about a boy who returns a lost wallet suggests the author wants to share a message about...','["fashion", "honesty", "speed", "weather"]'::jsonb,1,'The message is about being honest.','original'),
('110.7.b.10.B',4,'An author explains a problem in the first paragraph and then offers solutions. How does this structure support the author''s purpose?','["it makes the text shorter", "it hides the problem", "it helps persuade the reader to take action", "it adds rhyme"]'::jsonb,2,'Problem-solution persuades.','original'),
('110.7.b.10.C',3,'Why does an author include a chart with numbers in an article about population?','["to decorate the page", "to hide facts", "to add dialogue", "to present data clearly"]'::jsonb,3,'Charts organize data.','original'),
('110.7.b.10.D',4,'"The old house groaned in the wind" uses what to create an image?','["personification", "a fact", "a date", "a prefix"]'::jsonb,0,'The house is given a human action.','original'),
('110.7.b.10.D',3,'Which phrase shows imagery?','["the word because", "the sweet smell of warm cinnamon rolls", "a list of numbers", "three plus four"]'::jsonb,1,'Sensory description creates imagery.','original'),
('110.7.b.10.E',3,'A story told by a character who uses the word "I" is written in...','["a list", "third-person point of view", "first-person point of view", "second person"]'::jsonb,2,'The narrator is in the story.','original'),
('110.7.b.10.F',3,'Which sentence shows a strong, excited voice?','["We went.", "It is okay.", "The day was.", "What an amazing, unbelievable day this has been!"]'::jsonb,3,'Strong word choice shows voice.','original'),
('110.7.b.10.G',3,'Why might an author use hyperbole in a funny story?','["to exaggerate for humor", "to hide the plot", "to give exact facts", "to define a word"]'::jsonb,0,'Hyperbole exaggerates.','original'),
('110.7.b.10.G',4,'Which sentence is an example of stereotyping?','["Some teenagers play soccer.", "All teenagers are lazy.", "Maya is a teenager.", "The teenager waited."]'::jsonb,1,'It makes a broad unfair claim about a group.','original'),
('110.7.b.10.G',3,'Why might an author include an anecdote in an article?','["to confuse the reader", "to replace the title", "to illustrate a point with a short true story", "to add stanzas"]'::jsonb,2,'Anecdotes make points relatable.','original'),
('110.7.b.11.A',2,'Which tool helps a writer organize ideas before drafting?','["a ruler", "a stapler", "an eraser", "a graphic organizer"]'::jsonb,3,'Organizers map ideas.','original'),
('110.7.b.11.B.i',3,'Which word works best as a transition to show a contrast?','["however", "first", "because", "then"]'::jsonb,0,'However signals a contrast.','original'),
('110.7.b.11.B.i',3,'An essay''s introduction should...','["list all the details", "state the topic and grab the reader''s attention", "end the story", "repeat the title only"]'::jsonb,1,'The introduction opens the piece.','original'),
('110.7.b.11.B.ii',4,'Which sentence adds the most specific detail about a trip to the beach?','["We went somewhere.", "We had fun.", "We built a three-foot sandcastle with towers made from shells.", "It was nice."]'::jsonb,2,'Specific facts add depth.','original'),
('110.7.b.11.C',3,'Which revision combines these sentences best? "The storm was loud. The storm was long."','["Storm was.", "The loud long.", "The was loud storm long.", "The storm was loud and long."]'::jsonb,3,'It combines ideas smoothly.','original'),
('110.7.b.11.C',3,'Which word best replaces "big" in "The big elephant crossed the river"?','["enormous", "small", "quick", "good"]'::jsonb,0,'Enormous is a stronger word.','original'),
('110.7.b.11.D.i',3,'Which sentence is a comma splice?','["The bus was late, so we waited inside.", "The bus was late, we waited inside.", "We waited inside.", "The bus was late."]'::jsonb,1,'Two sentences are joined only by a comma.','original'),
('110.7.b.11.D.i',3,'Which sentence has subject-verb agreement?','["The dogs runs in the park.", "The dogs running in the park.", "The dogs run in the park.", "The dog run in the park."]'::jsonb,2,'Plural subject takes a plural verb.','original'),
('110.7.b.11.D.ii',3,'Which is the correct past tense of "begin"?','["beginned", "begined", "begun", "began"]'::jsonb,3,'Begin becomes began.','original'),
('110.7.b.11.D.ii',3,'Which sentence uses the correct past tense of "teach"?','["My aunt taught me to knit.", "My aunt tought me to knit.", "My aunt teached me to knit.", "My aunt teaches me yesterday."]'::jsonb,0,'Taught is the past tense of teach.','original'),
('110.7.b.11.D.iii',3,'Which word is a collective noun?','["feather", "flock", "bird", "fly"]'::jsonb,1,'A flock is a group of birds.','original'),
('110.7.b.11.D.iii',3,'Which sentence uses a collective noun?','["He ate quickly.", "The sky is blue.", "The team practices every day.", "Mia ran."]'::jsonb,2,'Team names a group.','original'),
('110.7.b.11.D.iv',3,'Which sentence uses the correct comparative form?','["This book is interestinger than that one.", "This book is most interesting than that one.", "This book is more interestinger than that one.", "This book is more interesting than that one."]'::jsonb,3,'Use more with longer adjectives.','original'),
('110.7.b.11.D.v',4,'Which word is a conjunctive adverb?','["however", "but", "and", "so"]'::jsonb,0,'However connects two ideas.','original'),
('110.7.b.11.D.v',3,'Which sentence uses a conjunctive adverb correctly?','["It rained all day therefore the game was canceled.", "It rained all day; therefore, the game was canceled.", "It rained therefore all day; the game was canceled.", "It rained all day, therefore the game was canceled."]'::jsonb,1,'A semicolon comes before and a comma after.','original'),
('110.7.b.11.D.vi',4,'Which sentence has subject-verb agreement when a prepositional phrase follows the subject?','["The box of crayons were on the table.", "The box of crayons are on the table.", "The box of crayons is on the table.", "The boxes of crayons is on the table."]'::jsonb,2,'The subject is box, not crayons.','original'),
('110.7.b.11.D.vii',3,'Which is an indefinite pronoun?','["she", "them", "myself", "everyone"]'::jsonb,3,'Everyone refers to no one specific.','original'),
('110.7.b.11.D.vii',3,'Which sentence uses an indefinite pronoun correctly?','["Everyone is ready for the trip.", "Everyone be ready for the trip.", "Everyone are ready for the trip.", "Everyone were ready for the trip."]'::jsonb,0,'Everyone takes a singular verb.','original'),
('110.7.b.11.D.viii',3,'Which sentence is a complex sentence?','["We stayed home and read.", "Because it was raining, we stayed home.", "It was raining.", "We stayed home."]'::jsonb,1,'It has a dependent clause.','original'),
('110.7.b.11.D.viii',3,'Which word is a subordinating conjunction?','["or", "but", "although", "and"]'::jsonb,2,'Although introduces a dependent clause.','original'),
('110.7.b.11.D.ix',3,'Which of these is an acronym written in all capital letters?','["library", "pencil", "teacher", "NASA"]'::jsonb,3,'Acronyms are capitalized.','original'),
('110.7.b.11.D.ix',3,'Which is a correctly written abbreviation for a title?','["Dr.", "mr", "ms", "prof"]'::jsonb,0,'A title abbreviation is capitalized and ends with a period.','original'),
('110.7.b.11.D.x',3,'Which sentence uses a comma correctly in a complex sentence?','["After, the game ended we went out for pizza.", "After the game ended, we went out for pizza.", "After the game ended we went, out for pizza.", "After the game, ended we went out for pizza."]'::jsonb,1,'A comma follows an introductory clause.','original'),
('110.7.b.11.D.x',3,'How should the title of a book be shown in handwriting or typing?','["all in lowercase", "in quotation marks only", "underlined or in italics", "crossed out"]'::jsonb,2,'Book titles are underlined or italicized.','original'),
('110.7.b.11.D.x',3,'Which sentence uses quotation marks and commas correctly?','["\"We should leave now\" said, Dad.", "We should leave now, \"said Dad.\"", "\"We should leave now said Dad.\"", "\"We should leave now,\" said Dad."]'::jsonb,3,'The comma goes inside the closing quotation mark.','original'),
('110.7.b.12.A',3,'Which element is important in fiction?','["characters facing a problem", "a table of contents", "a glossary", "a bibliography"]'::jsonb,0,'Fiction has characters and plot.','original'),
('110.7.b.12.A',3,'A personal narrative is told from the writer''s...','["science textbook", "own experience", "imagination about dragons only", "neighbor''s diary"]'::jsonb,1,'It is about the writer''s life.','original'),
('110.7.b.12.B',3,'An informational composition about the planets should include...','["a rhyming poem", "only the writer''s opinion", "facts organized around a central idea", "a made-up story"]'::jsonb,2,'Informational writing uses facts.','original'),
('110.7.b.12.C',3,'Which sentence best states an opinion for an opinion essay?','["Recess is a word.", "The bell rings at noon.", "We have a playground.", "Our school should have a longer recess."]'::jsonb,3,'It states a claim.','original'),
('110.7.b.12.C',3,'Which closing sentence best restates the claim in an opinion essay about recycling?','["For all these reasons, everyone should recycle.", "I like cake.", "The end.", "Then it rained."]'::jsonb,0,'A conclusion restates the claim.','original'),
('110.7.b.12.D',3,'Which sentence belongs in a letter requesting information from a zoo?','["Give me camps now.", "Could you please send me information about your summer camps?", "Zoos have animals.", "I am bored."]'::jsonb,1,'It politely asks for information.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
